#!/bin/sh
# Transport interop fixture (M2 `transport` area, decisions.md D21: test infrastructure only; nothing of it
# ships): one private OpenSSH 9.6 sshd inside WSL with every KEX method, host key type, cipher and MAC the
# client implements enabled at once, including the legacy ones, so the client side can drive the whole
# KEX x host-key matrix by restricting its own lists. Host keys: ed25519, ECDSA P-384, ECDSA P-521,
# RSA-2048; host certificates (own host CA) for the RSA and P-384 keys. Runs as the WSL user, never as
# root; the system sshd, /etc/ssh and ~/.ssh are not touched. The M2 matrix fixtures (../matrix) cover
# OpenSSH 10 / ML-KEM, ECDSA P-256 host keys, certificates on ed25519 and key rotation.
#
#   fixture.sh start | stop [--purge] | status
#
# Environment: SD_TR_PORT (default 2250). Listens on 127.0.0.1 and, in WSL's NAT mode, on the eth0
# address (state/env: direct_host). Server state: ~/.local/state/shelldrive-transport/.
set -eu

PORT="${SD_TR_PORT:-2250}"
HERE="$(cd "$(dirname "$0")" && pwd)"
STATE_WIN="$HERE/state"
RUN="${XDG_STATE_HOME:-$HOME/.local/state}/shelldrive-transport"
SSHD=/usr/sbin/sshd
USER_NAME="$(id -un)"

direct_addr() {
  if [ "${SD_SSHD_DIRECT:-1}" != "0" ] && command -v wslinfo >/dev/null 2>&1 &&
     [ "$(wslinfo --networking-mode 2>/dev/null || true)" = "nat" ]; then
    ip -4 -o addr show dev eth0 2>/dev/null | awk '{print $4}' | cut -d/ -f1 | head -n 1
  fi
}

running() { [ -f "$RUN/sshd.pid" ] && kill -0 "$(cat "$RUN/sshd.pid")" 2>/dev/null; }

do_start() {
  if [ ! -x "$SSHD" ]; then echo "sshd not found: sudo apt install openssh-server" >&2; exit 1; fi
  mkdir -p "$RUN" "$STATE_WIN"
  chmod 700 "$RUN"
  DIRECT="$(direct_addr)"
  [ -f "$RUN/host_ed25519" ] || ssh-keygen -q -t ed25519 -N '' -C sd-tr-host -f "$RUN/host_ed25519"
  [ -f "$RUN/host_ecdsa384" ] || ssh-keygen -q -t ecdsa -b 384 -N '' -C sd-tr-host -f "$RUN/host_ecdsa384"
  [ -f "$RUN/host_ecdsa521" ] || ssh-keygen -q -t ecdsa -b 521 -N '' -C sd-tr-host -f "$RUN/host_ecdsa521"
  [ -f "$RUN/host_rsa" ] || ssh-keygen -q -t rsa -b 2048 -N '' -C sd-tr-host -f "$RUN/host_rsa"
  [ -f "$RUN/host_ca" ] || ssh-keygen -q -t ed25519 -N '' -C sd-tr-host-ca -f "$RUN/host_ca"
  [ -f "$RUN/client_ed25519" ] || ssh-keygen -q -t ed25519 -N '' -C sd-tr-client -f "$RUN/client_ed25519"
  principals="127.0.0.1,localhost${DIRECT:+,$DIRECT}"
  for k in host_rsa host_ecdsa384; do
    if [ ! -f "$RUN/$k-cert.pub" ] || [ "$(cat "$RUN/$k.principals" 2>/dev/null)" != "$principals" ]; then
      ssh-keygen -q -s "$RUN/host_ca" -I "sd-tr-$k" -h -n "$principals" -V always:forever "$RUN/$k.pub"
      echo "$principals" > "$RUN/$k.principals"
    fi
  done
  cp "$RUN/client_ed25519.pub" "$RUN/authorized_keys"
  chmod 600 "$RUN"/host_* "$RUN/client_ed25519" "$RUN/authorized_keys"
  chmod 644 "$RUN"/*.pub

  cat > "$RUN/sshd_config" <<CONF
# Generated by tests/fixtures/transport/fixture.sh. Private test instance; not the system sshd.
Port $PORT
ListenAddress 127.0.0.1
${DIRECT:+ListenAddress $DIRECT}
HostKey $RUN/host_ed25519
HostKey $RUN/host_ecdsa384
HostKey $RUN/host_ecdsa521
HostKey $RUN/host_rsa
HostCertificate $RUN/host_rsa-cert.pub
HostCertificate $RUN/host_ecdsa384-cert.pub
PidFile $RUN/sshd.pid
AuthorizedKeysFile $RUN/authorized_keys
AllowUsers $USER_NAME
PermitRootLogin no
UsePAM no
PubkeyAuthentication yes
PasswordAuthentication no
KbdInteractiveAuthentication no
StrictModes no
MaxAuthTries 10
MaxStartups 100:30:200
KexAlgorithms curve25519-sha256,curve25519-sha256@libssh.org,ecdh-sha2-nistp256,ecdh-sha2-nistp384,ecdh-sha2-nistp521,diffie-hellman-group-exchange-sha256,diffie-hellman-group16-sha512,diffie-hellman-group18-sha512,diffie-hellman-group14-sha256,diffie-hellman-group14-sha1,diffie-hellman-group-exchange-sha1,diffie-hellman-group1-sha1
HostKeyAlgorithms ssh-ed25519,ecdsa-sha2-nistp384,ecdsa-sha2-nistp521,rsa-sha2-512,rsa-sha2-256,ssh-rsa,rsa-sha2-512-cert-v01@openssh.com,rsa-sha2-256-cert-v01@openssh.com,ssh-rsa-cert-v01@openssh.com,ecdsa-sha2-nistp384-cert-v01@openssh.com
Ciphers chacha20-poly1305@openssh.com,aes256-gcm@openssh.com,aes128-gcm@openssh.com,aes256-ctr,aes192-ctr,aes128-ctr,aes256-cbc,aes192-cbc,aes128-cbc,3des-cbc
MACs hmac-sha2-256-etm@openssh.com,hmac-sha2-512-etm@openssh.com,hmac-sha2-256,hmac-sha2-512,hmac-sha1-etm@openssh.com,hmac-sha1
Subsystem sftp internal-sftp
LogLevel VERBOSE
CONF
  if running; then kill "$(cat "$RUN/sshd.pid")" 2>/dev/null || true; sleep 0.3; fi
  "$SSHD" -t -f "$RUN/sshd_config"
  "$SSHD" -f "$RUN/sshd_config" -E "$RUN/sshd.log"
  i=0
  while [ $i -lt 50 ]; do [ -f "$RUN/sshd.pid" ] && break; sleep 0.1; i=$((i + 1)); done

  cp "$RUN/client_ed25519" "$STATE_WIN/"
  {
    echo "user=$USER_NAME"
    echo "port=$PORT"
    echo "key=client_ed25519"
    if [ -n "$DIRECT" ]; then echo "direct_host=$DIRECT"; fi
    echo "host_ca=$(cut -d' ' -f1,2 "$RUN/host_ca.pub")"
    for k in host_ed25519 host_ecdsa384 host_ecdsa521 host_rsa; do echo "hostkey=$(cut -d' ' -f1,2 "$RUN/$k.pub")"; done
  } > "$STATE_WIN/env"
  echo "transport fixture sshd on port $PORT (pid $(cat "$RUN/sshd.pid" 2>/dev/null || echo "?"), log $RUN/sshd.log)"
}

do_stop() {
  if running; then kill "$(cat "$RUN/sshd.pid")" 2>/dev/null || true; fi
  rm -f "$RUN/sshd.pid" "$STATE_WIN/env"
  if [ "${1:-}" = "--purge" ]; then rm -rf "$RUN" "$STATE_WIN"; fi
  echo "transport fixture stopped"
}

case "${1:-start}" in
  start) if running && [ -f "$STATE_WIN/env" ] && [ "${2:-}" != "--restart" ]; then echo "already running"; else do_start; fi ;;
  stop) do_stop "${2:-}" ;;
  status) if running; then echo "running (pid $(cat "$RUN/sshd.pid"))"; else echo "stopped"; exit 3; fi ;;
  *) echo "usage: fixture.sh start [--restart] | stop [--purge] | status" >&2; exit 2 ;;
esac
